def draw_car(grid, anchor=3):
    """Each anchor cell grows a car: a 5x5 cabin of 5s/2s centered on it and a full-width 2-row with a 5-wide 8 floor beneath."""
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    for r,c in [(i,j) for i in range(h) for j in range(w) if grid[i][j]==anchor]:
        for k,rowpat in enumerate([['5']*5,['2','0','5','0','2'],['2','0',str(anchor),'0','2'],['2','0','0','0','2']]):
            for k2,ch in enumerate(rowpat):
                if ch!='0': out[r-2+k][c-2+k2]=int(ch)
        out[r+2]=[2]*w
        for k2 in range(5): out[r+2][c-2+k2]=8
    return out
